<script setup lang="ts">
import{onMounted,ref}from"vue";import{useRoute,useRouter}from"vue-router";import{ArrowLeft,MagicStick}from"@element-plus/icons-vue";import{api}from"@/api";import{useProfileStore}from"@/stores/profile";import{useUserStore}from"@/stores/user";import{err,text}from"@/utils/format";import type{JobDetail,MatchedJob}from"@/types/api";import StateView from"@/components/common/StateView.vue";import SectionPanel from"@/components/common/SectionPanel.vue";import BarChart from"@/components/charts/BarChart.vue";
const route=useRoute(),router=useRouter(),user=useUserStore(),profiles=useProfileStore(),job=ref<JobDetail|null>(null),match=ref<MatchedJob|null>(null),loading=ref(true),matching=ref(false),error=ref("");async function load(){loading.value=true;try{job.value=await api.job(String(route.params.id))}catch(e){error.value=err(e)}finally{loading.value=false}}async function runMatch(){matching.value=true;try{await profiles.load(user.userId!);const r=await api.match({skills:profiles.profile!.skills.map(x=>x.name),top_k:20,user_id:user.userId});match.value=r.matches.find(x=>x.job_id===job.value?.job_id)||null;if(!match.value)error.value="该岗位未进入本次匹配结果，请补充相关技能后重试"}catch(e){error.value=err(e)}finally{matching.value=false}}onMounted(load);
</script><template><div><div class="detail-back"><el-button :icon="ArrowLeft" text @click="router.back()">返回岗位列表</el-button></div><StateView :loading="loading" :error="error&&!job?error:''" :empty="!job" @retry="load"><template #content><div class="job-detail-head"><div><el-tag>{{job?.category}}</el-tag><h2>{{job?.title}}</h2><div class="tag-row"><el-tag v-for="t in job?.tags" :key="t" type="info" effect="plain">{{t}}</el-tag></div></div><el-button type="primary" :icon="MagicStick" :loading="matching" @click="runMatch">分析我的匹配度</el-button></div><div class="detail-layout"><SectionPanel title="岗位说明"><div class="markdown-text">{{text(job?.content)}}</div></SectionPanel><aside><SectionPanel v-if="match" title="我的匹配情况"><div class="score-large">{{match.match_score}}<small>%</small></div><BarChart :labels="['综合匹配度']" :values="[match.match_score]"/><h4>已掌握技能</h4><div class="tag-row"><el-tag v-for="x in match.matched_skills" :key="x" type="success">{{x}}</el-tag></div><h4>待提升技能</h4><div class="tag-row"><el-tag v-for="x in match.missing_skills" :key="x" type="warning">{{x}}</el-tag></div><p v-if="match.match_reason" class="callout">{{match.match_reason}}</p></SectionPanel><SectionPanel v-else title="我的匹配情况"><StateView empty empty-text="尚未进行匹配"><el-button type="primary" plain @click="runMatch">立即分析</el-button></StateView></SectionPanel></aside></div></template></StateView></div></template>
